	protected void flushXReqQueue(Throwable exc) {
		List<DefaultRemoteAsyncResult> copy;
		lock (xReqQueue) {
			copy = List.copyOf(xReqQueue);
			xReqQueue.clear();
		}
		foreach (DefaultRemoteAsyncResult result in copy) {
			result.completeExceptionally(exc);
		}
	}

	protected void terminateTerminals() {
		List<TerminalSession> terminals;
		lock (this.terminals) {
			terminals = List.copyOf(this.terminals);
			this.terminals.clear();
		}
		foreach (TerminalSession term in terminals) {
			CompletableFuture.runAsync(() => {
				try {
					term.terminate();
				}
				catch (Exception e) {
					Msg.error(this, "Could not terminate " + term + ": " + e);
				}
			});
		}
	}

	public void dispose()
    {
		plugin.removeHandler(this);
		flushXReqQueue(new TraceRmiError("Socket closed"));

		terminateTerminals();

		socket.close();
		lock (openTxes) {
			while (!openTxes.isEmpty()) {
				Tid nextKey = openTxes.keySet().iterator().next();
				OpenTx openTx = openTxes.remove(nextKey);
				openTx.tx.close();
			}
		}

		foreach (OpenTrace open in openTraces.clearAll()) {
			if (traceManager == null || traceManager.isSaveTracesByDefault()) {
				try
{
    using (CloseableTaskMonitor monitor = plugin.createMonitor())
    {

					open.trace.save("Save on Disconnect", monitor);
				
    }
}
				catch (IOException e) {
					Msg.error(this, "Could not save " + open.trace);
				}
				catch (CancelledException e) {
					// OK. Move on
				}
			}
			open.dispose(this);
		}
		closed.complete(null);
		plugin.listeners.invoke().disconnected(this);
	}

