	protected static Span makeSpan(Lifespan lifespan) {
		if (lifespan.isEmpty()) {
			return Span.newBuilder().setMin(0).setMax(-1).build();
		}
		return Span.newBuilder().setMin(lifespan.lmin()).setMax(lifespan.lmax()).build();
	}

