	protected static Value makeValue(object value) {
		switch (value) {
			case Void v: return Value.newBuilder().setNullValue(Null.getDefaultInstance()).build();
			case Boolean b: return Value.newBuilder().setBoolValue(b).build();
			case Byte b: return Value.newBuilder().setByteValue(b).build();
			case Character c: return Value.newBuilder().setCharValue(c).build();
			case Short s: return Value.newBuilder().setShortValue(s).build();
			case Integer i: return Value.newBuilder().setIntValue(i).build();
			case Long l: return Value.newBuilder().setLongValue(l).build();
			case string s: return Value.newBuilder().setStringValue(s).build();
			case bool[] ba => Value.newBuilder()
					.setBoolArrValue(
						BoolArr.newBuilder().addAllArr(Arrays.asList(ArrayUtils.toObject(ba))))
					.build();
			case byte[] ba: return Value.newBuilder().setBytesValue(ByteString.copyFrom(ba)).build();
			case char[] ca: return Value.newBuilder().setCharArrValue(new string(ca)).build();
			case short[] sa => Value.newBuilder()
					.setShortArrValue(ShortArr.newBuilder()
							.addAllArr(
								Stream.of(ArrayUtils.toObject(sa)).map(s => (int) s).toList()))
					.build();
			case int[] ia => Value.newBuilder()
					.setIntArrValue(
						IntArr.newBuilder().addAllArr(IntStream.of(ia).mapToObj(i => i).toList()))
					.build();
			case long[] la => Value.newBuilder()
					.setLongArrValue(
						LongArr.newBuilder().addAllArr(LongStream.of(la).mapToObj(l => l).toList()))
					.build();
			case string[] sa => Value.newBuilder()
					.setStringArrValue(StringArr.newBuilder().addAllArr(List.of(sa)))
					.build();
			case Address a: return Value.newBuilder().setAddressValue(makeAddr(a)).build();
			case AddressRange r: return Value.newBuilder().setRangeValue(makeAddrRange(r)).build();
			case TraceObject o: return Value.newBuilder().setChildDesc(makeObjDesc(o)).build();
			default: throw new AssertionError(
				"Cannot encode value: " + value + "(type=" + value.GetType() + ")");
		};
	}

	protected static MethodArgument makeArgument(string name, object value) {
		return MethodArgument.newBuilder().setName(name).setValue(makeValue(value)).build();
	}

	protected static MethodArgument makeArgument(Map.Entry<string, object> ent) {
		return makeArgument(ent.getKey(), ent.getValue());
	}

